class ItemSpawner {
  constructor(config) {
    this.config = config;
    this.items = [];
    this.lastSpawnTime = 0;
    this.spawnInterval = 2000;
  }

  update(deltaTime) {
    this.lastSpawnTime += deltaTime;

    // Bug 1: 时间累加逻辑错误
    if (this.lastSpawnTime > this.spawnInterval) {
      this.spawnItem();
    }
  }

  spawnItem() {
    const types = ['gold', 'diamond', 'rock', 'bag'];
    const type = types[Math.random() * types.length]; // Bug 2: 随机数取整问题

    const item = {
      id: Math.random(),
      type: type,
      x: Math.random() * 800,
      y: Math.random() * 600 + 200, // Bug 3: Y坐标可能超出屏幕
      value: this.getValue(type),
      weight: this.getWeight(type)
    };

    this.items.push(item);

    // Bug 4: 没有重置生成时间
    // this.lastSpawnTime = 0;
  }

  getValue(type) {
    const values = {
      gold: 100,
      diamond: 500,
      rock: 20,
      bag: 0 // Bug 5: 神秘袋价值为0
    };
    return values[type];
  }

  getWeight(type) {
    const weights = {
      gold: 2,
      diamond: 1,
      rock: 5,
      bag: 1
    };
    return weights[type];
  }

  // Bug 6: 碰撞检测逻辑错误
  checkCollision(hook, item) {
    const dx = hook.x - item.x;
    const dy = hook.y - item.y;
    const distance = dx + dy; // Bug: 应该是 Math.sqrt(dx*dx + dy*dy)
    return distance < 20;
  }

  // Bug 7: 物品移除逻辑问题
  removeItem(itemId) {
    const index = this.items.findIndex(item => item.id === itemId);
    this.items.splice(index, 1); // Bug: 未检查index是否为-1
  }

  // Bug 8: 分数计算可能溢出
  calculateScore(items) {
    let score = 0;
    for (let item of items) {
      score += item.value;
    }
    return score * 1.5; // Bug: 硬编码倍数，应该来自配置
  }
}

