// 修复后的代码 - 黄金矿工物品生成系统
class ItemSpawner {
  constructor(config) {
    this.config = config || {};
    this.items = [];
    this.spawnTimer = 0; // 重命名避免混淆
    this.spawnInterval = config?.spawnInterval || 2000;
    this.screenWidth = config?.screenWidth || 800;
    this.screenHeight = config?.screenHeight || 600;
    this.spawnArea = config?.spawnArea || { minY: 200, maxY: 550 };
  }

  update(deltaTime) {
    this.spawnTimer += deltaTime * 1000; // 转换为毫秒

    // Fix 1 & 4: 正确的时间判断和重置
    if (this.spawnTimer >= this.spawnInterval) {
      this.spawnItem();
      this.spawnTimer = 0;
    }
  }

  spawnItem() {
    const types = ['gold', 'diamond', 'rock', 'bag'];
    // Fix 2: 正确的随机索引
    const type = types[Math.floor(Math.random() * types.length)];

    // Fix 3: 正确的Y坐标范围
    const y = this.spawnArea.minY + Math.random() * (this.spawnArea.maxY - this.spawnArea.minY);

    const item = {
      id: 'item_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
      type: type,
      x: Math.random() * (this.screenWidth - 50) + 25, // 留边距
      y: y,
      value: this.getValue(type),
      weight: this.getWeight(type),
      createdAt: Date.now()
    };

    this.items.push(item);
    console.log(`Spawned ${type} at (${item.x.toFixed(0)}, ${item.y.toFixed(0)})`);
  }

  getValue(type) {
    const values = {
      gold: 100,
      diamond: 500,
      rock: 20,
      // Fix 5: 神秘袋有随机价值
      bag: Math.floor(Math.random() * 200) + 50
    };
    return values[type] || 10;
  }

  getWeight(type) {
    const weights = {
      gold: 2,
      diamond: 1,
      rock: 5,
      bag: 1
    };
    return weights[type] || 1;
  }

  // Fix 6: 正确的距离计算
  checkCollision(hook, item) {
    const dx = hook.x - item.x;
    const dy = hook.y - item.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    const collisionThreshold = this.config?.collisionRadius || 20;
    return distance < collisionThreshold;
  }

  // Fix 7: 安全的物品移除
  removeItem(itemId) {
    const index = this.items.findIndex(item => item.id === itemId);
    if (index !== -1) {
      const removed = this.items.splice(index, 1)[0];
      console.log(`Removed item: ${removed.type}`);
      return removed;
    }
    console.warn(`Item ${itemId} not found`);
    return null;
  }

  // Fix 8: 从配置读取倍数
  calculateScore(items) {
    let score = 0;
    for (let item of items) {
      score += item.value;
    }
    const multiplier = this.config?.scoreMultiplier || 1.0;
    return Math.floor(score * multiplier);
  }

  // 新增：获取所有物品
  getItems() {
    return [...this.items];
  }

  // 新增：清理过期物品
  cleanup(maxAge = 30000) {
    const now = Date.now();
    this.items = this.items.filter(item => now - item.createdAt < maxAge);
  }
}

// 修复后的代码 - 钩子控制
class HookController {
  constructor(config = {}) {
    this.angle = 90; // 初始角度（度）
    this.speed = config.swingSpeed || 2;
    this.direction = 1;
    this.isExtending = false;
    this.length = 0;
    this.maxLength = config.maxLength || 300;
    this.extendSpeed = config.extendSpeed || 150; // 像素/秒
    this.retractSpeed = config.retractSpeed || 200;
    this.minAngle = config.minAngle || 30;
    this.maxAngle = config.maxAngle || 150;
    this.origin = config.origin || { x: 400, y: 100 };
    this.state = 'idle'; // idle, extending, retracting
  }

  // Fix 9 & 10: 正确的角度计算和边界检查
  update(deltaTime) {
    // 摆动状态
    if (this.state === 'idle') {
      this.angle += this.speed * this.direction;

      // 完整的边界检查
      if (this.angle >= this.maxAngle) {
        this.angle = this.maxAngle;
        this.direction = -1;
      } else if (this.angle <= this.minAngle) {
        this.angle = this.minAngle;
        this.direction = 1;
      }
    }

    // Fix 11: 逐帧更新而非while循环
    if (this.state === 'extending') {
      this.length += this.extendSpeed * deltaTime;
      if (this.length >= this.maxLength) {
        this.length = this.maxLength;
        this.state = 'retracting';
      }
    }

    if (this.state === 'retracting') {
      this.length -= this.retractSpeed * deltaTime;
      if (this.length <= 0) {
        this.length = 0;
        this.state = 'idle';
      }
    }
  }

  getPosition() {
    // Fix 9: 度数转弧度
    const radian = (this.angle * Math.PI) / 180;
    return {
      x: this.origin.x + Math.cos(radian) * this.length,
      y: this.origin.y + Math.sin(radian) * this.length
    };
  }

  extend() {
    if (this.state === 'idle') {
      this.state = 'extending';
      this.isExtending = true;
    }
  }

  retract() {
    this.state = 'retracting';
    this.isExtending = false;
  }

  grab(item) {
    this.grabbedItem = item;
    this.retractSpeed = this.calculateRetractSpeed(item);
    this.retract();
  }

  calculateRetractSpeed(item) {
    const weightFactor = Math.max(0.3, 1 - (item.weight * 0.15));
    return this.retractSpeed * weightFactor;
  }

  reset() {
    this.state = 'idle';
    this.length = 0;
    this.isExtending = false;
    this.grabbedItem = null;
  }
}

// 导出模块
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ItemSpawner, HookController };
}
